const basePatients=[
 {id:'DT-2048',name:'سارا محمدی',age:'۲۶ سال',treatment:'الاینر شفاف',stage:'مرحله ۱۴ از ۲۴',activity:'اسکن جدید · امروز',cooperation:96,status:'new',tone:'#568f88'},
 {id:'DT-1983',name:'امیر رضایی',age:'۱۹ سال',treatment:'براکت ثابت',stage:'ماه ۸ از ۱۸',activity:'پیام جدید · ۲ ساعت پیش',cooperation:82,status:'review',tone:'#8272a9'},
 {id:'DT-2115',name:'نازنین کریمی',age:'۳۲ سال',treatment:'الاینر شفاف',stage:'مرحله ۶ از ۲۰',activity:'اسکن دیرهنگام · ۴ روز',cooperation:68,status:'late',tone:'#bf7a67'},
 {id:'DT-1764',name:'پارسا اکبری',age:'۲۱ سال',treatment:'براکت ثابت',stage:'ماه ۱۳ از ۲۰',activity:'اسکن ثبت شد · دیروز',cooperation:92,status:'good',tone:'#477ba1'},
 {id:'DT-2071',name:'هلیا نوروزی',age:'۲۴ سال',treatment:'الاینر شفاف',stage:'مرحله ۱۰ از ۱۸',activity:'اسکن تکمیلی لازم',cooperation:88,status:'review',tone:'#7b9a57'}
];
let patients=[...basePatients];
let activeFilter='all',selectedRole='doctor',currentPatient=patients[0],detailTab='overview';
const labels={new:['اسکن جدید','good'],review:['نیازمند بررسی','review'],late:['تاخیر در اسکن','late'],good:['مناسب','good']};
const $=s=>document.querySelector(s);const $$=s=>[...document.querySelectorAll(s)];
const initials=name=>name.split(' ').map(x=>x[0]).join('');
function fa(n){return Number(n).toLocaleString('fa-IR')}
function toast(text){const el=$('#toast');el.textContent=text;el.classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>el.classList.remove('show'),2600)}
function showOnly(id){['login-screen','doctor-app','patient-detail','patient-app'].forEach(x=>$('#'+x).hidden=x!==id);window.scrollTo(0,0)}
function openModal(title,body){$('#modal-title').textContent=title;$('#modal-body').innerHTML=body;$('#modal-layer').hidden=false;setTimeout(()=>$('#modal-layer input, #modal-layer textarea')?.focus(),0)}
function closeModal(){$('#modal-layer').hidden=true}

function doctorPatients(){return `<section class="hero-strip"><div><span class="pulse"></span><b>مرکز پایش امروز</b><p>۳ بیمار به بررسی شما نیاز دارند.</p></div><button class="text-button" id="important-link">مشاهده موارد مهم ←</button></section>
<section class="metrics" aria-label="خلاصه وضعیت"><article><span class="metric-icon mint">◉</span><div><small>بیماران فعال</small><strong>۱۲۸</strong><p><i>+۸</i> این ماه</p></div></article><article><span class="metric-icon amber">⌁</span><div><small>نیازمند بررسی</small><strong>۱۲</strong><p>۳ مورد مهم</p></div></article><article><span class="metric-icon blue">◫</span><div><small>اسکن‌های این هفته</small><strong>۴۷</strong><p><i>۸۷٪</i> به‌موقع</p></div></article><article><span class="metric-icon violet">◎</span><div><small>میانگین همکاری</small><strong>۹۱٪</strong><p><i>+۴٪</i> نسبت به ماه قبل</p></div></article></section>
<section class="workspace"><div class="section-head"><div><h2>بیماران</h2><p>آخرین وضعیت درمان و فعالیت بیماران شما</p></div><div class="tools"><label class="search"><span>⌕</span><input id="patient-search" type="search" placeholder="جست‌وجوی نام یا کد بیمار"></label><button class="outline" id="filter-button">فیلترها</button></div></div><div class="filter-row" id="filter-row"><button class="chip active" data-filter="all">همه <span>۱۲۸</span></button><button class="chip" data-filter="review">نیازمند بررسی <span>۱۲</span></button><button class="chip" data-filter="new">اسکن جدید <span>۸</span></button><button class="chip" data-filter="late">تاخیر در اسکن <span>۴</span></button></div><div class="table-card"><table><thead><tr><th>بیمار</th><th>نوع درمان</th><th>مرحله</th><th>آخرین فعالیت</th><th>همکاری</th><th>وضعیت</th><th></th></tr></thead><tbody id="patient-table"></tbody></table><div class="empty" id="empty-state" hidden><b>بیماری پیدا نشد</b><span>عبارت جست‌وجو یا فیلترها را تغییر دهید.</span></div></div></section>`}
function doctorTasks(){return `<div class="view-title"><h2>فهرست وظایف</h2><p>کارهای امروز و مواردی که نیاز به تصمیم شما دارند</p></div><div class="task-list">${[['بررسی اسکن جدید سارا محمدی','ارسال‌شده امروز ساعت ۰۹:۲۰','امروز'],['پاسخ به پیام امیر رضایی','درد براکت پایین سمت چپ','امروز'],['تایید مرحله بعدی هلیا نوروزی','مرحله ۱۰ تکمیل شده است','امروز'],['پیگیری اسکن نازنین کریمی','۴ روز از موعد گذشته','فوری'],['بازبینی برنامه پارسا اکبری','ویزیت حضوری هفته آینده','فردا'],['ارسال یادآوری گروهی','برای ۶ بیمار با اسکن این هفته','فردا']].map((x,i)=>`<article class="task-card"><input type="checkbox" data-task="${i}" aria-label="تکمیل وظیفه"><div><b>${x[0]}</b><small>${x[1]}</small></div><time>${x[2]}</time></article>`).join('')}</div>`}
function doctorMessages(){return `<div class="view-title"><h2>پیام‌ها</h2><p>گفت‌وگوهای اخیر با بیماران</p></div><div class="message-list">${patients.slice(0,4).map((p,i)=>`<article class="task-card" data-open-message="${p.id}"><span class="avatar" style="background:${p.tone}">${initials(p.name)}</span><div><b>${p.name}</b><small>${['سلام دکتر، تصویر امروز را ارسال کردم.','از دیشب براکت کمی اذیتم می‌کند.','ممنون، مرحله بعد را شروع می‌کنم.','اسکن این هفته ثبت شد.'][i]}</small></div><time>${['۱۰ دقیقه','۲ ساعت','دیروز','۲ روز'][i]}</time></article>`).join('')}</div>`}
function doctorInsights(){return `<div class="view-title"><h2>بینش‌های مرکز درمانی</h2><p>روند همکاری بیماران و حجم اسکن‌های ثبت‌شده</p></div><div class="insight-grid"><article class="panel"><div class="panel-head"><h3>اسکن‌های هفتگی</h3><span class="status good">روند رو به رشد</span></div><div class="chart">${[55,70,62,88,76,93,84].map((h,i)=>`<div class="bar" style="height:${h}%"><span>${['ش','ی','د','س','چ','پ','ج'][i]}</span></div>`).join('')}</div></article><article class="panel"><h3>میانگین همکاری بیماران</h3><div class="donut"></div><p style="text-align:center;color:#75898d">۵٪ بهتر از فصل گذشته</p></article></div>`}
function doctorSettings(){return `<div class="view-title"><h2>تنظیمات</h2><p>اطلاعات مرکز و تنظیمات پایش</p></div><div class="detail-grid"><article class="panel"><h3>مشخصات مرکز</h3><div class="form-grid"><label class="full">نام مرکز<input value="کلینیک ارتودنسی دکتر نادری"></label><label>شماره تماس<input value="۰۲۱ ۸۸۷۷ ۱۲۳۴"></label><label>بازه پاسخ‌گویی<input value="۸ تا ۱۸"></label></div><button class="primary save-settings" style="margin-top:16px">ذخیره تغییرات</button></article><article class="panel"><h3>یادآوری‌ها</h3><div class="info-list"><div class="info-row"><span>یادآوری اسکن</span><b>۲۴ ساعت قبل</b></div><div class="info-row"><span>هشدار تاخیر</span><b>پس از ۲ روز</b></div><div class="info-row"><span>گزارش هفتگی</span><b>شنبه‌ها</b></div></div></article></div>`}

function renderDoctor(view='patients'){$('#doctor-title').textContent=view==='patients'?'صبح بخیر، دکتر نادری':({tasks:'فهرست وظایف',messages:'پیام‌ها',insights:'بینش‌ها',settings:'تنظیمات'}[view]);$('#doctor-content').innerHTML=({patients:doctorPatients,tasks:doctorTasks,messages:doctorMessages,insights:doctorInsights,settings:doctorSettings}[view])();if(view==='patients')bindPatientList();if(view==='tasks')$$('[data-task]').forEach(x=>x.onchange=()=>toast(x.checked?'وظیفه انجام شد':'وظیفه دوباره فعال شد'));if(view==='messages')$$('[data-open-message]').forEach(x=>x.onclick=()=>openPatientDetail(x.dataset.openMessage,'communication'));$('.save-settings')?.addEventListener('click',()=>toast('تنظیمات ذخیره شد'))}
function bindPatientList(){const search=$('#patient-search'),table=$('#patient-table');function renderRows(){const q=search.value.trim();const rows=patients.filter(p=>(activeFilter==='all'||p.status===activeFilter||(activeFilter==='review'&&p.status==='late'))&&(!q||p.name.includes(q)||p.id.toLowerCase().includes(q.toLowerCase())));table.innerHTML=rows.map(p=>`<tr data-id="${p.id}"><td><div class="patient"><span class="avatar" style="background:${p.tone}">${initials(p.name)}</span><div><b>${p.name}</b><small>${p.age} · ${p.id}</small></div></div></td><td>${p.treatment}</td><td>${p.stage}</td><td>${p.activity}</td><td><b>${fa(p.cooperation)}٪</b><div class="progress"><i style="width:${p.cooperation}%"></i></div></td><td><span class="status ${labels[p.status][1]}">${labels[p.status][0]}</span></td><td>←</td></tr>`).join('');$('#empty-state').hidden=rows.length>0;$$('tbody tr[data-id]').forEach(r=>r.onclick=()=>openPatientDetail(r.dataset.id))}search.oninput=renderRows;$$('.chip').forEach(btn=>btn.onclick=()=>{$$('.chip').forEach(x=>x.classList.remove('active'));btn.classList.add('active');activeFilter=btn.dataset.filter;renderRows()});$('#important-link').onclick=()=>{$('[data-filter="review"]').click();$('#filter-row').scrollIntoView({behavior:'smooth'})};renderRows()}

function overviewTemplate(){return `<div class="detail-grid"><div><article class="panel"><div class="panel-head"><h2>آخرین مانیتورینگ</h2><span class="status good">حرکت مطابق برنامه</span></div><div class="scan-compare"><div class="scan-card"><b>اسکن مرحله قبل</b><small>۲۳ شهریور ۱۴۰۵</small></div><span>←</span><div class="scan-card"><b>اسکن جدید</b><small>امروز، ساعت ۰۹:۲۰</small></div></div></article><article class="panel" style="margin-top:14px"><div class="panel-head"><h3>مشاهدات هوش مصنوعی</h3><button class="link-btn" data-tab-jump="ai">مشاهده کامل</button></div><div class="ai-note"><b>هم‌راستایی دندان‌های قدامی بهتر شده است.</b><p>حرکت ثبت‌شده با مرحله ۱۴ برنامه درمان هم‌خوانی دارد.</p></div><div class="ai-note"><b>پایش بهداشت دهان</b><p>التهاب خفیف لثه در سمت چپ دیده می‌شود؛ بررسی پزشک پیشنهاد می‌شود.</p></div></article></div><aside><article class="panel"><h3>اطلاعات درمان</h3><div class="info-list"><div class="info-row"><span>مرحله فعلی</span><b>${currentPatient.stage}</b></div><div class="info-row"><span>الاینر فعلی</span><b>شماره ۱۴</b></div><div class="info-row"><span>تعویض بعدی</span><b>۳ روز دیگر</b></div><div class="info-row"><span>ویزیت بعدی</span><b>۱۴ مهر</b></div></div><div class="goal"><div><b>پیشرفت درمان</b><span>۵۸٪</span></div><div class="progress"><i style="width:58%"></i></div></div></article><article class="panel note-form" style="margin-top:14px"><h3>یادداشت پزشک</h3><textarea id="doctor-note" placeholder="یادداشت جدید برای پرونده..."></textarea><button class="primary" id="save-note">ثبت یادداشت</button></article></aside></div>`}
function monitoringTemplate(){return `<div class="detail-grid"><article class="panel"><div class="panel-head"><h2>تاریخچه مانیتورینگ</h2><button class="outline">ساخت مقایسه تصویری</button></div><div class="timeline"><div class="timeline-item"><b>مرحله ۱۴ · اسکن تایید شد</b><small>۳۰ شهریور · حرکت مناسب، نیاز به اقدام ندارد</small></div><div class="timeline-item"><b>مرحله ۱۳ · پیام یادآوری</b><small>۲۳ شهریور · بیمار اسکن را همان روز ارسال کرد</small></div><div class="timeline-item"><b>مرحله ۱۲ · درخواست تصویر تکمیلی</b><small>۱۶ شهریور · نمای بایت تکمیل شد</small></div><div class="timeline-item"><b>مرحله ۱۱ · تایید تعویض الاینر</b><small>۹ شهریور · همکاری عالی</small></div></div></article><aside class="panel"><h3>گزارش هفتگی</h3><div class="info-list"><div class="info-row"><span>زمان استفاده</span><b>۲۱.۵ ساعت</b></div><div class="info-row"><span>ثبت اسکن</span><b>به‌موقع</b></div><div class="info-row"><span>کیفیت تصاویر</span><b>عالی</b></div><div class="info-row"><span>وضعیت</span><b>ادامه درمان</b></div></div></aside></div>`}
function planTemplate(){return `<div class="detail-grid"><article class="panel"><h2>برنامه درمان</h2>${[['آماده‌سازی و ثبت اولیه',100],['اصلاح نامرتبی قدامی',100],['هماهنگی قوس‌ها',58],['تکمیل بایت و فینیشینگ',12],['دوره نگهدارنده',0]].map(x=>`<div class="goal"><div><b>${x[0]}</b><span>${fa(x[1])}٪</span></div><div class="progress"><i style="width:${x[1]}%"></i></div></div>`).join('')}</article><aside class="panel"><h3>اقدام بعدی</h3><p>پس از تایید اسکن امروز، بیمار می‌تواند الاینر شماره ۱۵ را شروع کند.</p><button class="primary plan-approve">تایید مرحله بعد</button></aside></div>`}
function timelineTemplate(){return `<article class="panel"><h2>خط زمانی درمان</h2><div class="timeline"><div class="timeline-item"><b>اسکن مانیتورینگ مرحله ۱۴</b><small>امروز · ارسال توسط بیمار</small></div><div class="timeline-item"><b>تعویض به الاینر شماره ۱۴</b><small>۲۳ شهریور · تایید دکتر نادری</small></div><div class="timeline-item"><b>ویزیت حضوری</b><small>۲ شهریور · IPR انجام شد</small></div><div class="timeline-item"><b>شروع درمان</b><small>۱۲ فروردین · تحویل ۶ ست اول</small></div></div></article>`}
function filesTemplate(){return `<article class="panel"><div class="panel-head"><h2>پرونده و فایل‌ها</h2><button class="primary upload-file">+ بارگذاری فایل</button></div>${[['طرح درمان نهایی.pdf','PDF · ۲.۴ مگابایت'],['پانورامیک اولیه.jpg','تصویر · ۱.۸ مگابایت'],['سفالومتری.jpg','تصویر · ۱.۲ مگابایت'],['رضایت‌نامه درمان.pdf','PDF · ۸۶۰ کیلوبایت']].map((x,i)=>`<div class="file-row"><span class="file-icon">${i===1||i===2?'▧':'▤'}</span><div><b>${x[0]}</b><small>${x[1]}</small></div><button class="outline file-open">مشاهده</button></div>`).join('')}</article>`}
function compareTemplate(){return `<article class="panel"><div class="panel-head"><h2>مقایسه شروع درمان و امروز</h2><button class="outline compare-export">دریافت تصویر مقایسه‌ای</button></div><div class="scan-compare"><div class="scan-card"><b>شروع درمان</b><small>۱۲ فروردین ۱۴۰۵</small></div><span>←</span><div class="scan-card"><b>وضعیت امروز</b><small>۳۰ شهریور ۱۴۰۵</small></div></div><p style="color:#71868a">این مقایسه برای نمایش روند درمان است و جایگزین ارزیابی پزشک نیست.</p></article>`}
function aiTemplate(){return `<div class="detail-grid"><article class="panel"><h2>مشاهدات هوش مصنوعی</h2><div class="ai-note"><b>ردیابی حرکت دندان ۱۱ و ۲۱</b><p>حرکت چرخشی با برنامه درمان هم‌خوانی دارد. اطمینان تحلیل: ۹۲٪</p></div><div class="ai-note"><b>بررسی نشستن الاینر</b><p>فاصله خفیف در ناحیه پرمولر بالا دیده می‌شود. بررسی تصویر تکمیلی پیشنهاد می‌شود.</p></div><div class="ai-note"><b>نشانه‌های بافت نرم</b><p>احتمال التهاب خفیف لثه در سمت چپ. تصمیم درمانی بر عهده پزشک است.</p></div></article><aside class="panel"><h3>جمع‌بندی پیشنهادی</h3><p>ادامه مرحله فعلی همراه با ارسال یک تصویر تکمیلی از نمای چپ.</p><button class="primary request-extra">درخواست تصویر تکمیلی</button></aside></div>`}
function goalsTemplate(){return `<article class="panel"><h2>اهداف درمانی</h2>${[['هم‌راستایی دندان‌های قدامی',82],['اصلاح اورجت',64],['هماهنگی قوس بالا و پایین',58],['بهبود خط لبخند',45]].map(x=>`<div class="goal"><div><b>${x[0]}</b><span>${fa(x[1])}٪</span></div><div class="progress"><i style="width:${x[1]}%"></i></div></div>`).join('')}</article>`}
function communicationTemplate(){return `<div class="detail-grid"><article class="panel"><h2>گفت‌وگو با ${currentPatient.name}</h2><div class="chat" id="doctor-chat"><div class="bubble">سلام دکتر، اسکن امروز را ارسال کردم.<small>امروز ۰۹:۲۰</small></div><div class="bubble me">ممنون سارا. تصاویر واضح هستند؛ نتیجه را همین‌جا اعلام می‌کنم.<small>امروز ۰۹:۳۸</small></div></div><div class="message-compose"><textarea id="doctor-message-text" placeholder="پیام خود را بنویسید..."></textarea><button class="primary" id="send-doctor-message">ارسال پیام</button></div></article><aside class="panel"><h3>پاسخ‌های سریع</h3><button class="ghost quick-reply">اسکن تایید شد؛ مرحله بعد را شروع کنید.</button><button class="ghost quick-reply" style="margin-top:8px">لطفاً یک تصویر از نمای چپ ارسال کنید.</button></aside></div>`}
const detailViews={overview:overviewTemplate,monitoring:monitoringTemplate,plan:planTemplate,timeline:timelineTemplate,files:filesTemplate,compare:compareTemplate,ai:aiTemplate,goals:goalsTemplate,communication:communicationTemplate};
function openPatientDetail(id,tab='overview'){currentPatient=patients.find(p=>p.id===id)||patients[0];detailTab=tab;$('#detail-code').textContent=currentPatient.id;$('#detail-name').textContent=currentPatient.name;$('#detail-avatar').textContent=initials(currentPatient.name);$('#detail-avatar').style.background=currentPatient.tone;$('#detail-meta').textContent=`${currentPatient.age} · ${currentPatient.treatment} · شروع درمان: ۱۲ فروردین ۱۴۰۵`;$('#detail-score').textContent=`${fa(currentPatient.cooperation)}٪`;showOnly('patient-detail');renderDetail()}
function renderDetail(){$$('#detail-tabs button').forEach(x=>x.classList.toggle('active',x.dataset.detailTab===detailTab));$('#detail-content').innerHTML=detailViews[detailTab]();$$('[data-tab-jump]').forEach(x=>x.onclick=()=>{detailTab=x.dataset.tabJump;renderDetail()});$('#save-note')?.addEventListener('click',()=>{const v=$('#doctor-note').value.trim();if(!v)return toast('متن یادداشت را وارد کنید');localStorage.setItem(`danto-note-${currentPatient.id}`,v);toast('یادداشت در نسخه نمایشی ذخیره شد')});$('.plan-approve')?.addEventListener('click',()=>toast('مرحله بعدی درمان تایید شد'));$('.upload-file')?.addEventListener('click',()=>toast('در نسخه نهایی فایل در فضای امن بیمار ذخیره می‌شود'));$('.compare-export')?.addEventListener('click',()=>toast('تصویر مقایسه‌ای آماده شد'));$('.request-extra')?.addEventListener('click',()=>toast('درخواست تصویر تکمیلی برای بیمار ارسال شد'));$$('.file-open').forEach(x=>x.onclick=()=>toast('پیش‌نمایش فایل باز شد'));$$('.quick-reply').forEach(x=>x.onclick=()=>{$('#doctor-message-text').value=x.textContent});$('#send-doctor-message')?.addEventListener('click',()=>{const t=$('#doctor-message-text').value.trim();if(!t)return toast('پیام را بنویسید');$('#doctor-chat').insertAdjacentHTML('beforeend',`<div class="bubble me">${escapeHtml(t)}<small>همین حالا</small></div>`);$('#doctor-message-text').value='';toast('پیام ارسال شد')})}

function patientHome(){return `<section class="patient-welcome"><article class="treatment-card"><span class="stage-pill">درمان فعال · الاینر شفاف</span><h2>مرحله ۱۴ از ۲۴</h2><p>روند درمان شما طبق برنامه پیش می‌رود. استفاده منظم از الاینر را ادامه دهید.</p><div class="treatment-progress"><div><span>شروع درمان</span><b>۵۸٪ انجام شده</b><span>پایان تقریبی</span></div><div class="progress"><i style="width:58%"></i></div></div></article><article class="scan-callout"><span class="scan-date">موعد بعدی: سه‌شنبه ۱ مهر</span><h2>اسکن هفتگی شما</h2><p>حدود ۳ دقیقه زمان می‌برد. بهتر است در نور مناسب عکس بگیرید.</p><button class="primary" data-patient-go="scans">شروع ثبت اسکن ←</button></article></section><section class="patient-stats"><article class="patient-stat"><small>میانگین استفاده روزانه</small><strong>۲۱.۵ ساعت</strong><span class="status good">عالی</span></article><article class="patient-stat"><small>همکاری شما</small><strong>۹۶٪</strong><span class="status good">روند مثبت</span></article><article class="patient-stat"><small>تعویض الاینر</small><strong>۳ روز دیگر</strong><span style="color:#7c8d90;font-size:.75rem">پس از تایید پزشک</span></article></section><section class="patient-grid"><article class="panel"><div class="panel-head"><h3>پیام دکتر نادری</h3><button class="link-btn" data-patient-go="messages">مشاهده گفتگو</button></div><div class="doctor-message"><div class="doctor-avatar">م‌ن</div><div><b>تصاویر این هفته واضح و مناسب هستند.</b><p>پس از بررسی نهایی، درباره شروع الاینر بعدی به شما اطلاع می‌دهم.</p><small>امروز، ساعت ۰۹:۳۸</small></div></div></article><article class="panel"><h3>پیشنهاد این هفته</h3><div class="education-card"><span class="file-icon">▶</span><div><b>تمیز کردن صحیح الاینر</b><small>ویدیوی آموزشی · ۲ دقیقه</small></div></div></article></section>`}
function patientRoadmap(){return `<div class="view-title"><h2>مسیر درمان من</h2><p>مراحل طی‌شده و قدم‌های بعدی درمان</p></div><article class="panel roadmap"><div class="roadmap-item done"><span class="roadmap-dot">✓</span><div><b>بررسی و طرح درمان</b><p>اسکن اولیه و تایید برنامه درمان</p><small>تکمیل‌شده در فروردین</small></div></div><div class="roadmap-item done"><span class="roadmap-dot">✓</span><div><b>شروع الاینرها</b><p>تحویل ست‌های ۱ تا ۶</p><small>تکمیل‌شده</small></div></div><div class="roadmap-item current"><span class="roadmap-dot">۱۴</span><div><b>هماهنگی قوس‌ها</b><p>در حال حاضر در مرحله ۱۴ از ۲۴ هستید.</p><small>مرحله فعلی</small></div></div><div class="roadmap-item"><span class="roadmap-dot">۴</span><div><b>فینیشینگ</b><p>تنظیمات نهایی بایت و خط لبخند</p><small>مرحله بعدی</small></div></div><div class="roadmap-item"><span class="roadmap-dot">۵</span><div><b>دوره نگهدارنده</b><p>تحویل ریتینر و پایش ثبات نتیجه</p></div></div></article>`}
function patientScans(){return `<div class="view-title"><h2>ثبت اسکن جدید</h2><p>سه تصویر واضح از روبه‌رو، راست و چپ ثبت کنید.</p></div><article class="panel"><div class="upload-zone"><b>تصاویر دهان و دندان را انتخاب کنید</b><p>فرمت JPG یا PNG، حداکثر ۱۰ مگابایت برای هر تصویر</p><input id="scan-input" type="file" accept="image/*" multiple capture="environment"><label class="primary" for="scan-input">انتخاب یا گرفتن عکس</label></div><div class="scan-preview" id="scan-preview"><div class="scan-slot">نمای روبه‌رو</div><div class="scan-slot">نمای راست</div><div class="scan-slot">نمای چپ</div></div><button class="primary" id="submit-scan" style="margin-top:16px;width:100%">ارسال اسکن برای پزشک</button></article><article class="panel" style="margin-top:14px"><h3>اسکن‌های قبلی</h3>${['۲۳ شهریور · تاییدشده','۱۶ شهریور · تصویر تکمیلی ارسال شد','۹ شهریور · تاییدشده'].map(x=>`<div class="file-row"><span class="file-icon">▣</span><b>${x}</b><span class="status good">ثبت شده</span></div>`).join('')}</article>`}
function patientMessages(){return `<div class="view-title"><h2>گفت‌وگو با پزشک</h2><p>پیام‌های درمانی خود را مستقیماً برای دکتر نادری بفرستید.</p></div><article class="panel"><div class="chat" id="patient-chat"><div class="bubble me">سلام دکتر، اسکن امروز را ارسال کردم.<small>امروز ۰۹:۲۰</small></div><div class="bubble">ممنون سارا. تصاویر واضح هستند؛ نتیجه را همین‌جا اعلام می‌کنم.<small>امروز ۰۹:۳۸</small></div></div><div class="message-compose"><textarea id="patient-message-text" placeholder="پیام خود را بنویسید..."></textarea><button class="primary" id="send-patient-message">ارسال پیام</button><button class="outline" id="urgent-report" style="margin-right:8px">گزارش وضعیت فوری</button></div></article>`}
function patientProfile(){return `<div class="view-title"><h2>حساب من</h2><p>اطلاعات شخصی و تنظیمات یادآوری</p></div><div class="detail-grid"><article class="panel"><h3>مشخصات</h3><div class="info-list"><div class="info-row"><span>نام و نام خانوادگی</span><b>سارا محمدی</b></div><div class="info-row"><span>کد پرونده</span><b>DT-2048</b></div><div class="info-row"><span>پزشک معالج</span><b>دکتر مریم نادری</b></div><div class="info-row"><span>شماره تماس</span><b>۰۹۱۲ *** ۴۸۲۱</b></div></div></article><aside class="panel"><h3>یادآوری‌ها</h3><div class="info-list"><div class="info-row"><span>یادآوری اسکن</span><b>فعال</b></div><div class="info-row"><span>تعویض الاینر</span><b>فعال</b></div><div class="info-row"><span>پیام پزشک</span><b>فعال</b></div></div></aside></div>`}
const patientViews={home:patientHome,roadmap:patientRoadmap,scans:patientScans,messages:patientMessages,profile:patientProfile};
function renderPatient(view='home'){const titles={home:'سلام سارا!',roadmap:'مسیر درمان',scans:'اسکن‌ها',messages:'پیام‌ها',profile:'حساب من'};$('#patient-page-title').textContent=titles[view];$('#patient-content').innerHTML=patientViews[view]();$$('[data-patient-view]').forEach(x=>x.classList.toggle('active',x.dataset.patientView===view));$$('[data-patient-go]').forEach(x=>x.onclick=()=>renderPatient(x.dataset.patientGo));if(view==='scans')bindScanUpload();if(view==='messages')bindPatientMessages()}
function bindScanUpload(){let count=0;$('#scan-input').onchange=e=>{const files=[...e.target.files].slice(0,3);count=files.length;const slots=$$('#scan-preview .scan-slot');files.forEach((f,i)=>{const url=URL.createObjectURL(f);slots[i].innerHTML=`<img src="${url}" alt="پیش‌نمایش تصویر ${i+1}">`});toast(`${fa(files.length)} تصویر انتخاب شد`)};$('#submit-scan').onclick=()=>count?toast('اسکن برای پزشک ارسال شد'):toast('ابتدا حداقل یک تصویر انتخاب کنید')}
function bindPatientMessages(){$('#send-patient-message').onclick=()=>{const t=$('#patient-message-text').value.trim();if(!t)return toast('پیام را بنویسید');$('#patient-chat').insertAdjacentHTML('beforeend',`<div class="bubble me">${escapeHtml(t)}<small>همین حالا</small></div>`);$('#patient-message-text').value='';toast('پیام ارسال شد')};$('#urgent-report').onclick=()=>openModal('گزارش وضعیت فوری',`<p>اگر مشکل تنفسی یا خونریزی شدید دارید، با اورژانس تماس بگیرید. برای مشکلات درمانی، موضوع را انتخاب کنید.</p><div class="form-grid"><label class="full">موضوع<select id="urgent-type"><option>شکستن براکت یا سیم</option><option>درد غیرعادی</option><option>گم شدن الاینر</option><option>زخم دهان</option></select></label><label class="full">توضیح کوتاه<input id="urgent-text" placeholder="چه اتفاقی افتاده است؟"></label></div><div class="modal-actions"><button class="outline" data-modal-cancel>انصراف</button><button class="primary" id="urgent-send">ارسال برای پزشک</button></div>`);setTimeout(()=>{$('[data-modal-cancel]').onclick=closeModal;$('#urgent-send').onclick=()=>{closeModal();toast('گزارش فوری برای پزشک ارسال شد')}},0)}
function escapeHtml(v){return v.replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}

$$('.role-card').forEach(card=>card.onclick=()=>{selectedRole=card.dataset.role;$$('.role-card').forEach(x=>x.classList.toggle('selected',x===card));$('#login-id').value=selectedRole==='doctor'?'doctor@danto.ir':'09121234567'});
$('#toggle-pass').onclick=()=>{$('#login-pass').type=$('#login-pass').type==='password'?'text':'password'};
$('#login-submit').onclick=()=>{if(!$('#login-id').value.trim()||!$('#login-pass').value.trim())return toast('اطلاعات ورود را کامل کنید');if(selectedRole==='doctor'){showOnly('doctor-app');renderDoctor()}else{showOnly('patient-app');renderPatient()}toast('با موفقیت وارد شدید')};
$$('[data-logout]').forEach(x=>x.onclick=()=>{showOnly('login-screen');toast('از حساب خارج شدید')});
$$('[data-doctor-view]').forEach(btn=>btn.onclick=()=>{$$('[data-doctor-view]').forEach(x=>x.classList.toggle('active',x===btn));renderDoctor(btn.dataset.doctorView);$('.sidebar').classList.remove('open')});
$$('[data-patient-view]').forEach(btn=>btn.onclick=()=>renderPatient(btn.dataset.patientView));
$$('[data-detail-tab]').forEach(btn=>btn.onclick=()=>{detailTab=btn.dataset.detailTab;renderDetail()});
$('.mobile-menu').onclick=()=>$('.sidebar').classList.toggle('open');
$('#detail-back').onclick=()=>{showOnly('doctor-app');renderDoctor('patients')};
$('#detail-message').onclick=()=>{detailTab='communication';renderDetail()};
$('#detail-action').onclick=()=>openModal('ثبت اقدام جدید',`<div class="form-grid"><label class="full">نوع اقدام<select id="action-type"><option>تایید مرحله بعد</option><option>درخواست اسکن تکمیلی</option><option>زمان‌بندی ویزیت</option><option>توقف موقت درمان</option></select></label><label class="full">توضیحات<input id="action-text" placeholder="توضیح اختیاری"></label></div><div class="modal-actions"><button class="outline" data-modal-cancel>انصراف</button><button class="primary" id="action-save">ثبت اقدام</button></div>`);
$('#add-patient').onclick=()=>openModal('افزودن بیمار جدید',`<div class="form-grid"><label class="full">نام و نام خانوادگی<input id="new-name" placeholder="مثلاً نگار احمدی"></label><label>شماره موبایل<input id="new-phone" placeholder="۰۹۱۲..." inputmode="tel"></label><label>نوع درمان<select id="new-treatment"><option>الاینر شفاف</option><option>براکت ثابت</option></select></label></div><div class="modal-actions"><button class="outline" data-modal-cancel>انصراف</button><button class="primary" id="new-save">ایجاد پرونده</button></div>`);
$('#doctor-notifications').onclick=()=>openModal('اعلان‌ها',`<div class="task-list"><div class="task-card"><span class="status review">جدید</span><div><b>اسکن سارا محمدی آماده بررسی است</b><small>۱۰ دقیقه پیش</small></div></div><div class="task-card"><span class="status late">مهم</span><div><b>اسکن نازنین کریمی ۴ روز تاخیر دارد</b><small>امروز</small></div></div></div>`);
$('#modal-close').onclick=closeModal;$('#modal-layer').onclick=e=>{if(e.target===$('#modal-layer'))closeModal()};
document.addEventListener('click',e=>{if(e.target.closest('[data-modal-cancel]'))closeModal();if(e.target.id==='action-save'){closeModal();toast('اقدام در پرونده ثبت شد')}if(e.target.id==='new-save'){const name=$('#new-name').value.trim();if(!name)return toast('نام بیمار را وارد کنید');const p={id:`DT-${2200+patients.length}`,name,age:'—',treatment:$('#new-treatment').value,stage:'در انتظار شروع',activity:'پرونده جدید',cooperation:0,status:'good',tone:'#648d91'};patients.unshift(p);closeModal();renderDoctor('patients');toast('پرونده بیمار ایجاد شد')}});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal()});

function registerWebMCP(){
  const ctx=document.modelContext;
  if(!ctx?.registerTool)return;
  const safeRegister=tool=>{try{Promise.resolve(ctx.registerTool(tool)).catch(()=>{})}catch{}};
  safeRegister({
    name:'open_patient_record',title:'باز کردن پرونده بیمار',description:'پرونده یک بیمار را با کد پرونده در داشبورد پزشک باز می‌کند.',
    inputSchema:{type:'object',properties:{patientId:{type:'string'}},required:['patientId'],additionalProperties:false},
    annotations:{readOnlyHint:true,untrustedContentHint:false},
    execute:input=>{if(!input||typeof input.patientId!=='string'||Object.keys(input).some(k=>k!=='patientId'))throw new Error('کد پرونده معتبر لازم است');const p=patients.find(x=>x.id===input.patientId);if(!p)throw new Error('بیمار پیدا نشد');openPatientDetail(input.patientId);return{id:p.id,name:p.name,status:labels[p.status][0]}}
  });
  safeRegister({
    name:'filter_patients',title:'فیلتر بیماران',description:'فهرست بیماران پزشک را بر اساس وضعیت فیلتر می‌کند.',
    inputSchema:{type:'object',properties:{status:{type:'string',enum:['all','review','new','late']}},required:['status'],additionalProperties:false},
    annotations:{readOnlyHint:true,untrustedContentHint:false},
    execute:input=>{const allowed=['all','review','new','late'];if(!input||!allowed.includes(input.status)||Object.keys(input).some(k=>k!=='status'))throw new Error('وضعیت فیلتر معتبر نیست');showOnly('doctor-app');renderDoctor('patients');$(`[data-filter="${input.status}"]`).click();return{status:input.status,visible:true}}
  });
  safeRegister({
    name:'start_patient_scan',title:'شروع ثبت اسکن بیمار',description:'بخش ثبت تصاویر اسکن را در داشبورد بیمار باز می‌کند.',
    inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},
    execute:input=>{if(input&&Object.keys(input).length)throw new Error('این ابزار ورودی نمی‌پذیرد');showOnly('patient-app');renderPatient('scans');return{view:'scans',ready:true}}
  })
}
registerWebMCP();
